import json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_11/projects/turn-hier-kv-compress/data/synthetic_traces/traces.json') as f:
    traces = json.load(f)

print(f'Total traces: {len(traces)}')
print(f'Total planted info: {sum(len(t[\"planted_info\"]) for t in traces)}')

# Check planted info role distribution
role_counts = {}
for t in traces:
    for pi in t['planted_info']:
        role = pi['location']['role']
        role_counts[role] = role_counts.get(role, 0) + 1
print(f'\\nPlanted info by role:')
for r, c in sorted(role_counts.items(), key=lambda x: -x[1]):
    print(f'  {r}: {c}')

# Check how many have info in thinking/assistant thinking blocks
thinking_planted = 0
for t in traces:
    for pi in t['planted_info']:
        if pi['location']['role'] == 'assistant':
            # Check if the message at that index contains <think>
            mi = pi['location']['message_index']
            if mi < len(t['messages']):
                msg = t['messages'][mi]
                if '<think>' in msg.get('content', ''):
                    thinking_planted += 1
print(f'\\nPlanted info in <think> blocks: {thinking_planted}')

# Complexity distribution
cx_counts = {}
for t in traces:
    cx = t['metadata']['complexity']
    cx_counts[cx] = cx_counts.get(cx, 0) + 1
print(f'\\nComplexity distribution:')
for cx, c in sorted(cx_counts.items()):
    print(f'  {cx}: {c}')

# Scenario distribution 
sc_counts = {}
for t in traces:
    sc = t['metadata']['scenario']
    sc_counts[sc] = sc_counts.get(sc, 0) + 1
print(f'\\nScenario distribution:')
for sc, c in sorted(sc_counts.items()):
    print(f'  {sc}: {c}')
"

